using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Threading.Tasks;using V15Voice;
public static class SubtitleRefineUiTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,v);}static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}static IEnumerable<Control> Walk(Control c){foreach(Control a in c.Controls){yield return a;foreach(var b in Walk(a))yield return b;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=async(s,e)=>{try{
 string root=Path.Combine(Path.GetTempPath(),"v149-refine-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"source","asr"));string media=Path.Combine(root,"existing.mp4");File.WriteAllText(media,"ORIGINAL");Set(f,"root",root);Call(f,"AddSubtitleFiles",new object[]{new[]{media}});var jobs=(List<SubtitleJob>)F(f,"subtitleQueue");var j=jobs.Last();j.Document=new SubtitleDocument{Duration=8,Cues=new List<SubtitleCue>{new SubtitleCue{Start=1,End=4,Text="He sees the the gas station."}}};j.Document.Save(j.Result);j.Output=j.Document.ExportBeside(media);string old=j.Output;Call(f,"RefreshSubtitleJobs");var page=(TabPage)F(f,"subtitlePage");((TabControl)F(f,"tabs")).SelectedTab=page;Check(Walk(page).OfType<Button>().Any(b=>b.Text=="Rà lỗi / chia lại"&&b.Visible),"Refine action is present on subtitles page");
 string script=Path.Combine(root,"source","asr","asr_worker.py");File.WriteAllText(script,"import sys,xml.etree.ElementTree as E,pathlib\na=sys.argv\npathlib.Path(__file__).with_name('command.txt').write_text(a[1])\nassert a[1]=='refine'\nassert a[a.index('--repetitions')+1]=='preserve'\nx=E.Element('subtitles',duration='8',pipeline='v1410-speech-1',model='fixture',device='cpu')\nE.SubElement(x,'cue',start='1',end='4',info='Two audio contexts').text='He sees the gas station.'\nE.SubElement(E.SubElement(x,'audit'),'change',kind='duplicate',removed='the')\nE.ElementTree(x).write(a[a.index('--output')+1],encoding='utf-8',xml_declaration=True)\n");await (Task)Call(f,"RefineSubtitle");Check(File.ReadAllText(Path.Combine(root,"source","asr","command.txt"))=="refine","Refine invokes the distinct production command");Check(j.Document.Cues[0].Text=="He sees the gas station."&&j.Document.Pipeline=="v1410-speech-1","Refined project and pipeline are loaded");Check(j.Document.Audit.Elements("change").Count()==1,"Correction audit survives refinement");Check(File.ReadAllText(old).Contains("the the")&&File.ReadAllText(j.Output).Contains("the gas"),"Previous SRT is preserved beside new result");Check(File.ReadAllText(media)=="ORIGINAL"&&!(bool)F(f,"busy"),"Source untouched and controls unlocked");
 File.WriteAllText(script,"import sys,time\nprint('waiting',flush=True)\ntime.sleep(60)\n");string before=j.Output;var task=(Task)Call(f,"RefineSubtitle");await Task.Delay(600);Call(f,"CancelTasks");await task;Check(j.Output==before&&File.Exists(before)&&!(bool)F(f,"busy"),"Stopping refinement preserves completed result");Console.WriteLine("TOTAL REFINE UI "+count+" passed.");
 }catch(Exception x){Console.WriteLine(x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
